valid_url_pattern = r"^https?://.*"

class SafeOpenTool(Tool):
    name = "safe_open_tool"
    description = """This is a tool that opens a file replacing open().
                     It enforces security by forcing file access to occur strictly within the designated safe directory.
                     Any directory paths provided in 'file_name' will be stripped."""
    inputs = {
        "file_name": {
            "type": "string",
            "description": "The name of the file to be opened. directory components are ignored; the file is looked up in the safe directory."
        },
        "mode": {
            "type": "string",
            "description": "'rt' for text files, 'rb' for binary files (pdf, docx...)"
        }
    }
    output_type = "object"

    def __init__(self, safe_dir):
        super().__init__()
        self.safe_dir = safe_dir
        # logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
        # logging.info("Secure SafeOpenTool initialized.")
        logging.info(f"SafeOpenTool initialized.\n*** ✅ ---> Files will be saved in '{os.path.abspath(self.safe_dir)}'")

    def forward(self, file_name, mode):
        # 1. Sanitize: Ignore whatever path the agent provided and force usage of basename
        #    Example: 'uploads/run1.csv' -> 'run1.csv'
        #    Example: 'C:/Windows/System32/run1.csv' -> 'run1.csv'
        clean_name = os.path.basename(file_name)

        # 2. Construct the forced path inside the safe directory
        file_path = os.path.join(self.safe_dir, clean_name)
        abs_file_path = os.path.abspath(file_path)
        abs_safe_dir = os.path.abspath(self.safe_dir)

        # 3. Security Verification (Double check)
        #    Ensure the resulting path is actually inside the safe dir
        if not abs_file_path.startswith(abs_safe_dir):
            raise ValueError(f"Access denied: File path {abs_file_path} is outside the allowed path {abs_safe_dir}")
        # logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
        # logging.info(f"SavePlotTool initialized.\n*** ✅ ---> Plots will be saved in '{os.path.abspath(self.safe_dir)}'")
        logging.info(f"SafeOpenTool: Opening '{abs_file_path}' in mode '{mode}'")

        try:
            if 'b' in mode:
                return open(abs_file_path, mode)
            else:
                # Default to text mode with utf-8 encoding
                return open(abs_file_path, mode, encoding='utf-8')
        except FileNotFoundError:
            raise FileNotFoundError(f"File not found: {clean_name} (looked in {abs_safe_dir})")

class PDFSplitterToolGv2(SafeOpenTool):
    name = "pdf_splitter_tool"
    description = """Splits a PDF into Markdown files. It ensures chunks do not break
                     in the middle of a paragraph by splitting at double newlines."""
    inputs = {
        "file_name": {
            "type": "string",
            "description": "The pathname or URL of the PDF file to be split."
        },
        "pages_per_chunk": {
            "type": "integer",
            "description": "Maximum number of pages per generated Markdown file."
        }
    }
    output_type = "string"

    def __init__(self, safe_dir):
        super().__init__(safe_dir)
        logging.info("Secure PDFSplitterToolGv2 initialized.")

    def forward(self, file_name, pages_per_chunk):
        # 1. Handle Input (Logic mirrored from PDF2TXTTool)
        if os.path.isfile(file_name) or not re.match(valid_url_pattern, file_name):
            # SafeOpenTool handles path stripping and security logic
            binary_file = super().forward(file_name, "rb")
        elif re.match(valid_url_pattern, file_name) is not None:
            # Handle Web URL
            logging.info(f"PDFSplitterTool: Downloading PDF from {file_name}")
            with httpx.stream("GET", file_name) as response:
                binary_file = io.BytesIO(b"".join(response.iter_raw()))
        else:
            raise ValueError(f"The string {file_name} is neither a web URL nor a valid path.")

        try:
            doc = fitz.open(stream=binary_file.read(), filetype="pdf")
            total_pages = len(doc)
            clean_base = os.path.splitext(os.path.basename(file_name))[0]

            all_created_files = []
            chunk_count = 1

            # This buffer will hold the "hanging" paragraph text from the previous chunk
            carry_over_text = ""

            for start_page in range(0, total_pages, pages_per_chunk):
                end_page = min(start_page + pages_per_chunk, total_pages)
                page_range = list(range(start_page, end_page))

                # Extract current range
                current_md = pymupdf4llm.to_markdown(doc, pages=page_range)

                # Prepend any text that was cut off from the previous iteration
                full_text = carry_over_text + current_md

                # If this is not the last chunk, we find the last logical break
                if end_page < total_pages:
                    # Look for the last double newline (paragraph break)
                    last_break = full_text.rfind("\n\n")

                    if last_break != -1:
                        # Split: 'content' goes to file, 'carry_over' goes to next loop
                        content = full_text[:last_break].strip()
                        carry_over_text = full_text[last_break:].strip() + "\n\n"
                    else:
                        # If no double newline found, keep all and clear carry_over
                        content = full_text
                        carry_over_text = ""
                else:
                    # Last chunk: take everything remaining
                    content = full_text

                # Save the content
                out_name = f"{clean_base}_part{chunk_count}_p{start_page+1}-{end_page}.md"
                out_path = os.path.join(self.safe_dir, out_name)

                with open(out_path, "w", encoding="utf-8") as f:
                    f.write(content)

                all_created_files.append(out_name)
                chunk_count += 1

            doc.close()
            return f"Created {len(all_created_files)} semantic chunks: {', '.join(all_created_files)}"

        except Exception as e:
            return f"Error: {str(e)}"

class PDF2TXTTool(SafeOpenTool):
    name = "pdf_2_txt_tool"
    description = """This is a tool that extracts the text from a PDF file.
                     If the file is not in a safe directory it raises an exception."""
    inputs = {
        "file_name": {
            "type": "string",
            "description": "The pathname or URL of the PDF file to be opened."
        }
    }
    output_type = "string"

    def __init__(self, safe_dir):
        super().__init__(safe_dir)
        # logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
        logging.info("Secure PDF2TXTTool initialized.")

    def forward(self, file_name):
        if os.path.isfile(file_name):
            # if it's a path to a local file:
            # binary_file = super().forward(file_name, "rb") # invoke SafeOpenTool
            binary_file = super().forward(file_name, "rb")  # invoke SafeOpenTool
        elif re.match(valid_url_pattern, file_name) is not None:
            # else, if it's a web link:
            with httpx.stream("GET", file_name) as response:
                binary_file = io.BytesIO(b"".join(response.iter_raw()))
        else:
            raise ValueError(f"The string {file_name} is neither a web URL nor a path to a local file")

        # Iterate through all the pages and extract text
        text = ""
        import fitz
        with fitz.open("pdf", binary_file.read()) as pdf:
            # Iterate through all the pages and extract text
            for page_number in range(len(pdf)):
                page = pdf[page_number]
                page_text = page.get_text()  # Extract text from the current page
                # print(f"****** New page of {file_name}:\n{page_text}")
                text += page_text
        binary_file.close()
        return text

class PDFAnalyzerTool(Tool):
    name = "pdf_analyzer_tool"
    description = """Analyzes a PDF file to determine the best text extraction method (direct vs. OCR).
                     It provides a detailed report on text content, images, and text readability.
                     The file must be located in the secure upload directory."""
    inputs = {
        "pdf_filename": {
            "type": "string",
            "description": "The name of the PDF file (e.g., 'report.pdf') located in the safe upload directory."
        },
        "min_readable_ratio": {
            "type": "number",  # <-- FIX IS HERE
            "description": "The minimum ratio of readable characters (0.0 to 1.0) to consider text directly extractable. Defaults to 0.7.",
            "nullable": True
        },
        "sample_pages": {
            "type": "integer",
            "description": "The number of pages to sample for a quick analysis of large documents. Defaults to 3.",
            "nullable": True
        }
    }
    output_type = "string"

    def __init__(self, safe_dir: str):
        super().__init__()
        self.safe_dir = safe_dir
        if not os.path.isdir(self.safe_dir):
            os.makedirs(self.safe_dir, exist_ok=True)
        # logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
        logging.info("Secure PDFAnalyzerTool initialized.")

    def _sample_pages(self, total_pages, sample_pages_count):
        if total_pages <= sample_pages_count:
            return list(range(total_pages))
        step = total_pages / sample_pages_count
        return [int(i * step) for i in range(sample_pages_count)]

    def _calculate_readable_ratio(self, text):
        if not text:
            return 0.0
        readable_pattern = r'[a-zA-Z0-9\s\.,;:!?\-\'\"()\[\]{}/@#$%&*+=<>|~`]'
        readable_chars = len(re.findall(readable_pattern, text))
        total_chars = len(text)
        return readable_chars / total_chars if total_chars > 0 else 0.0

    def _recommend_method(self, results):
        has_text = results["has_text"]
        has_images = results["has_images"]
        is_readable = results["text_is_readable"]
        avg_readable = results["avg_readable_ratio"]

        if not has_text and has_images:
            return "OCR_REQUIRED", 0.95
        if not has_text and not has_images:
            return "EMPTY_OR_UNSUPPORTED", 0.95
        if has_text and is_readable:
            confidence = 0.95 if not has_images else 0.85
            return "DIRECT_EXTRACTION", confidence
        if has_text and not is_readable:
            if avg_readable < 0.3:
                return "OCR_REQUIRED", 0.90
            else:
                return "HYBRID", 0.70
        return "HYBRID", 0.50

    def _format_report(self, results):
        report_lines = []
        if "error" in results:
            report_lines.append("=" * 70)
            report_lines.append("PDF ANALYSIS ERROR")
            report_lines.append("=" * 70)
            report_lines.append(f"\nError: {results['error']}")
            if "path" in results:
                report_lines.append(f"Path: {results['path']}")
            report_lines.append("=" * 70)
            return "\n".join(report_lines)

        report_lines.append("=" * 70)
        report_lines.append("PDF TEXT EXTRACTION ANALYSIS REPORT")
        report_lines.append("=" * 70)
        report_lines.append("\nDocument Info:")
        report_lines.append(f"  Total Pages: {results['total_pages']}")
        report_lines.append(f"  Pages Sampled: {results['sampled_pages']}")
        report_lines.append("\nContent Detection:")
        report_lines.append(f"  Has Text Layer: {results['has_text']}")
        report_lines.append(f"  Has Images: {results['has_images']}")
        report_lines.append(f"  Text is Readable: {results['text_is_readable']}")
        report_lines.append(f"  Avg Readable Ratio: {results['avg_readable_ratio']:.2%}")

        report_lines.append("\nPer-Page Analysis:")
        for page in results['page_analysis']:
            report_lines.append(f"  Page {page['page_num']}:")
            report_lines.append(f"    Text Length: {page['text_length']} chars")
            report_lines.append(f"    Has Text: {page['has_text']}")
            report_lines.append(f"    Has Images: {page['has_images']}")
            report_lines.append(f"    Readable Ratio: {page['readable_ratio']:.2%}")

        report_lines.append("\n" + "=" * 70)
        report_lines.append(f"RECOMMENDATION: {results['recommended_method']}")
        report_lines.append(f"Confidence: {results['confidence']:.0%}")
        report_lines.append("=" * 70)

        method = results['recommended_method']
        report_lines.append("\nNext Steps:")
        if method == 'DIRECT_EXTRACTION':
            report_lines.append("  ✓ Use direct text extraction (e.g., pdf_2_txt_tool).")
        elif method == 'OCR_REQUIRED':
            report_lines.append("  ✓ Use OCR tools. Direct text extraction will likely fail.")
        elif method == 'HYBRID':
            report_lines.append("  ⚠ This PDF is mixed. Try direct extraction first, but be prepared to use OCR if results are poor.")
        else:
            report_lines.append("  ⚠ Document may be empty, corrupted, or use an unsupported format.")

        return "\n".join(report_lines)

    def forward(self, pdf_filename: str, min_readable_ratio: float = 0.7, sample_pages: int = 3):
        full_path = os.path.abspath(os.path.join(self.safe_dir, os.path.basename(pdf_filename)))
        safe_dir_abs = os.path.abspath(self.safe_dir)

        if not full_path.startswith(safe_dir_abs):
            return self._format_report({"error": f"Access denied. File '{pdf_filename}' is outside the safe directory.", "path": full_path})

        if not os.path.exists(full_path):
            return self._format_report({"error": "File not found", "path": full_path})

        try:
            doc = fitz.open(full_path)
        except Exception as e:
            return self._format_report({"error": f"Error opening PDF: {str(e)}", "path": full_path})

        total_pages = len(doc)
        if total_pages == 0:
            doc.close()
            return self._format_report({"error": "PDF document is empty (0 pages).", "path": full_path})

        page_indices = self._sample_pages(total_pages, sample_pages)

        results = {
            "total_pages": total_pages,
            "sampled_pages": len(page_indices),
            "has_text": False,
            "has_images": False,
            "text_is_readable": False,
            "avg_readable_ratio": 0.0,
            "page_analysis": [],
        }

        total_readable_ratio = 0.0
        for page_num in page_indices:
            page = doc.load_page(page_num)
            page_text = page.get_text()
            has_images = len(page.get_images(full=True)) > 0
            has_text = len(page_text.strip()) > 0

            results["has_text"] |= has_text
            results["has_images"] |= has_images

            readable_ratio = self._calculate_readable_ratio(page_text) if has_text else 0.0
            total_readable_ratio += readable_ratio

            results["page_analysis"].append({
                "page_num": page_num,
                "text_length": len(page_text),
                "has_text": has_text,
                "has_images": has_images,
                "readable_ratio": readable_ratio
            })

        doc.close()

        if len(page_indices) > 0:
            results["avg_readable_ratio"] = total_readable_ratio / len(page_indices)

        results["text_is_readable"] = results["avg_readable_ratio"] >= min_readable_ratio

        results["recommended_method"], results["confidence"] = self._recommend_method(results)

        return self._format_report(results)

class OCR2TXTTool(Tool):
    name = "ocr_2_txt_tool"
    description = """Extracts text from PDF files using Optical Character Recognition (OCR).
                     This tool is essential for scanned documents, PDFs containing only images, or when PDFAnalyzerTool recommends 'OCR_REQUIRED' or 'HYBRID'.
                     It is more resource-intensive than the standard pdf_2_txt_tool.
                     The file must be located in the secure upload directory."""
    inputs = {
        "file_name": {
            "type": "string",
            "description": "The name of the PDF file (e.g., 'scanned_report.pdf') located in the safe upload directory."
        },
        "language": {
            "type": "string",
            "description": "The language of the text in the document (e.g., 'eng' for English, 'ita' for Italian, 'fra' for French). Defaults to 'eng'.",
            "nullable": True
        }
    }
    output_type = "string"

    def __init__(self, safe_dir: str):
        super().__init__()
        self.safe_dir = os.path.abspath(safe_dir)
        if not os.path.isdir(self.safe_dir):
            os.makedirs(self.safe_dir, exist_ok=True)
        # logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
        logging.info("Secure OCR2TXTTool initialized.")

        # --- Proactive Dependency Check during Initialization ---
        tesseract_path = shutil.which('tesseract')
        if not tesseract_path:
            raise ImportError(
                "Tesseract is not installed or not in your PATH. "
                "OCR2TXTTool cannot function without it. "
                "Please install Tesseract-OCR for your system."
            )
        logging.info(f"Tesseract executable found at: {tesseract_path}")

        # pdf2image depends on Poppler
        pdftoppm_path = shutil.which('pdftoppm')
        if not pdftoppm_path:
            raise ImportError(
                "Poppler is not installed or not in your PATH. "
                "OCR2TXTTool depends on pdf2image, which requires Poppler. "
                "Please install poppler-utils (on Linux) or Poppler for your system."
            )
        logging.info(f"Poppler (pdftoppm) executable found at: {pdftoppm_path}")

    def forward(self, file_name: str, language: str = 'eng'):
        # --- Security: Sanitize and validate the file path ---
        full_path = os.path.abspath(os.path.join(self.safe_dir, os.path.basename(file_name)))

        if not full_path.startswith(self.safe_dir):
            return f"Error: Access denied. File '{file_name}' is outside the safe directory."

        if not os.path.exists(full_path):
            return f"Error: File not found at '{full_path}'."

        try:
            logging.info(f"Starting OCR process for '{full_path}' with language '{language}'.")
            # Convert PDF to a list of PIL images
            images = convert_from_path(full_path)

            full_text = []
            for i, image in enumerate(images):
                logging.info(f"  - Performing OCR on page {i + 1}/{len(images)}")
                # Use pytesseract to extract text from the image
                text = pytesseract.image_to_string(image, lang=language)
                full_text.append(text)

            logging.info(f"Successfully completed OCR for '{full_path}'.")
            # Join the text from all pages
            return "\n\n--- Page Break ---\n\n".join(full_text)

        except Exception as e:
            error_message = f"An error occurred during the OCR process: {str(e)}"
            logging.error(error_message)
            return f"Error: {error_message}"

